"""Machine-authored exact sparse division of experimental certificates."""
from reverse_certificate_beca0ad5 import O
import json
from collections import Counter,defaultdict
def divide(p,c,ds):
 p=dict(p);q=defaultdict(int)
 # Monic in k. Polynomial division over Z[s].
 while p:
  e=max(p,key=lambda e:(e[0],e[1]));v=p[e]
  if e[0]==0:return None
  a,b=e[0]-1,e[1];q[a,b]+=v
  for ee,vv in [(e,v),((a,b),c*v),((a,b+1),ds*v)]:
   if vv:
    p[ee]=p.get(ee,0)-vv
    if p[ee]==0:del p[ee]
 return dict(q)
def run():
 out=[]
 for h in range(2,13):
  p={tuple(e):v for e,v in json.loads((O/f'reverse-certificate-h{h}.json').read_text())}
  factors=[]
  for c in range(1,2*h+7):
   for ds in [0,1]:
    while True:
     q=divide(p,c,ds)
     if q is None:break
     factors.append([c,ds]);p=q
  D=Counter(h+3+t-i for t in [0,2,1,1] for i in range(h))
  for c,ds in factors:
   if ds:D[c]-=1
  row=dict(h=h,factors=factors,remaining_denominator=dict(sorted(D.items())),terms=len(p),negative=sum(v<0 for v in p.values()),degree=max(map(sum,p)),polynomial=[[list(e),v] for e,v in sorted(p.items())])
  out.append(row);print(json.dumps({k:v for k,v in row.items() if k!='polynomial'}),flush=True)
 (O/'factored-reverse-certificates.json').write_text(json.dumps(out,indent=2)+'\n')
if __name__=='__main__':run()

"""Machine-authored exact formal-polynomial experiment, not a Lean proof.
For each fixed h, clear positive falling-factorial denominators after j=h+k.
Coefficient positivity in nonnegative k,s is tested exactly, not inferred.
"""
from pathlib import Path
from collections import defaultdict
import json,time,hashlib
O=Path('/Users/sasha/math_gkm/evidence/markov-beca0ad5')
def mul_linear(p,c,ds=1):
 q=defaultdict(int)
 for (k,s),v in p.items():
  q[k,s]+=c*v;q[k+1,s]+=v
  if ds:q[k,s+1]+=v
 return {e:v for e,v in q.items() if v}
def w(r):return 1 if r==0 else 4*r
def term(h,rs):
 # slots have parameter shifts 0,2,1,1.
 p={(0,0):1}
 for r in rs:
  for i in range(r):p=mul_linear(p,h-i,0)
 for t,r in zip([0,2,1,1],rs):
  for i in range(r,h):p=mul_linear(p,h+3+t-i)
 return p
def certificate(h):
 p=defaultdict(int)
 for a in range(h+1):
  b=h-a
  for c in range(h):
   d=h-1-c
   scale=w(a)*w(b)*w(c)*w(d)
   for e,v in term(h,[a,b,c,d]).items():p[e]+=scale*v
   for e,v in term(h,[c,d,a,b]).items():p[e]-=scale*v
 return {e:v for e,v in p.items() if v}
def run():
 start=time.monotonic();out=dict(status='exact polynomial experiment, no universal h theorem',cases=[])
 for h in range(2,13):
  p=certificate(h);neg=[(list(e),v) for e,v in p.items() if v<0]
  item=dict(h=h,terms=len(p),negative=len(neg),first_negative=neg[:3],degree=max(map(sum,p)),constant=p.get((0,0),0))
  out['cases'].append(item)
  (O/f'reverse-certificate-h{h}.json').write_text(json.dumps([[list(e),v] for e,v in sorted(p.items())],indent=2)+'\n')
  print(json.dumps(item),flush=True)
 out['seconds']=time.monotonic()-start;out['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
 (O/'reverse-certificate-probe.json').write_text(json.dumps(out,indent=2)+'\n')
if __name__=='__main__':run()

"""Machine-authored beca0ad5. Actual source recurrence experiment, not proof."""
from pathlib import Path
from math import comb
import json,time,hashlib
from three_probe_9e205206 import frame
from source_experiment_6576ccc5 import correction
from source_experiment_9647c1ba import L
O=Path('/Users/sasha/math_gkm/evidence/markov-beca0ad5')
def save(name,out,start):
    out['seconds']=time.monotonic()-start
    out['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    (O/name).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out),flush=True)
def run():
    start=time.monotonic();out=dict(status='finite exact actual-source experiment, not proof',fractions=0,rows=0,coefficients=0,zeros=0,raw_triples=[0,0,0],failures=[])
    for q in list(range(2,25))+[31,40]:
        for r in [False,True]:
            a,b,p=frame([False]*(q-1)+[True,r]);out['fractions']+=1
            for k in range((q-(2 if r else 1))//2+1):
                d=q-2*k-(2 if r else 1);j=q+k+1;out['rows']+=1
                for i in range(b+6):
                    raw=p.get((i,j),0);out['coefficients']+=1;out['zeros']+=raw==0
                    if raw!=L(d,j,i-3)+correction(d,k,i-2,r):out['failures'].append(['source identity',q,r,k,i])
            def inside(i,j):return a*b<=b*i+a*j and i+j<=a+b-1
            for i in range(a+b+1):
                for j in range(a+b+1-i):
                    for direction,pts in enumerate([[(i,j),(i+1,j),(i+2,j)],[(i,j),(i,j+1),(i,j+2)],[(i,j+2),(i+1,j+1),(i+2,j)]]):
                        if all(inside(*z) for z in pts):
                            vals=[p.get(z,0) for z in pts];out['raw_triples'][direction]+=1
                            if vals[0]*vals[2]>vals[1]**2:out['failures'].append(['raw inequality',q,r,direction,pts,vals])
    save('source-experiment.json',out,start)
if __name__=='__main__':run()

"""Machine-authored exact independent checks of the new representations.
Finite computations only. Source-family experiment is recorded separately.
"""
from pathlib import Path
from math import comb,prod
from fractions import Fraction as F
from itertools import permutations,combinations_with_replacement
import json,time,hashlib,random
from probe_beca0ad5 import check
O=Path('/Users/sasha/math_gkm/evidence/markov-beca0ad5')
def w(r):return 0 if r<0 else 1 if r==0 else 4*r
def fall(n,r):return prod(range(n-r+1,n+1)) if 0<=r<=n else 0
def rk(j,s,r):return F(w(r)*fall(j,r),fall(s+j+3,r))
def cv(j,s,t,h):return sum(rk(j,s,r)*rk(j,t,h-r) for r in range(h+1))
def ck(j,s,h,r):return w(r)*fall(j,r)*fall(s+j+3-r,h-r)
def cc(j,s,t,h,m):return sum(ck(j,s,h,r)*ck(j,t,h,m-r) for r in range(m+1))
def raw(j,s,t,n):return sum(w(j-i)*w(j-n+i)*comb(s+i+3,i)*comb(t+n-i+3,n-i) for i in range(max(0,n-j),min(j,n)+1))
def determinant(a):
 return sum((-1)**sum(p[i]>p[j] for i in range(4) for j in range(i+1,4))*prod(w(a[i]-i+p[i]) for i in range(4)) for p in permutations(range(4)))
def run():
 start=time.monotonic();out=dict(status='finite exact checks, not proof',reverse_formulas=0,cleared_formulas=0,polynomial_identities=0,determinants=0,forbidden_zeros=0,top_gaps=0,failures=[])
 for j in range(1,41):
  for s in [0,1,4,10]:
   for h in range(j+1):
    for t in [s,s+2]:
     out['reverse_formulas']+=1
     r=cv(j,s,t,h)
     if raw(j,s,t,2*j-h)!=comb(s+j+3,j)*comb(t+j+3,j)*r:out['failures'].append(['reverse',j,s,t,h])
     out['cleared_formulas']+=1
     if cc(j,s,t,h,h)!=fall(s+j+3,h)*fall(t+j+3,h)*r:out['failures'].append(['cleared',j,s,t,h])
 for h in range(2,13):
  p=json.loads((O/f'reverse-certificate-h{h}.json').read_text())
  for k in [0,1,3,10,50]:
   for s in [0,1,4,20]:
    j=h+k
    gap=cc(j,s+1,s+1,h,h-1)*cc(j,s,s+2,h,h)-cc(j,s+1,s+1,h,h)*cc(j,s,s+2,h,h-1)
    value=sum(v*k**e[0]*s**e[1] for e,v in p)
    out['polynomial_identities']+=1
    if value!=gap:out['failures'].append(['polynomial',h,k,s,value,gap])
 for a in range(17):
  for b in range(a+1):
   for c in range(b+1):
    for d in range(c+1):
     value=determinant([a,b,c,d]);out['determinants']+=1
     expected=0 if c>=3 else 16*(a-b+1)*(1+(c==1)+(d==1)) if b>=2 else 1 if a==0 else 4*((2*(b+c+d)+1)*a-(b+c+d))
     out['forbidden_zeros']+=c>=3
     if value!=expected:out['failures'].append(['det',a,b,c,d,value,expected])
 for j in range(3,121):
  for s in range(21):
   x=s+j+3
   g2=cv(j,s+1,s+1,1)*cv(j,s,s+2,2)-cv(j,s+1,s+1,2)*cv(j,s,s+2,1)
   expected=F(128*j*j*(j-1)*(2*x+1),x*x*(x-1)*(x+1)**2*(x+2))
   out['top_gaps']+=1
   if g2!=expected:out['failures'].append(['second gap',j,s])
 out['seconds']=time.monotonic()-start;out['script_sha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
 (O/'representation-experiment.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out),flush=True)
 # Reproduce the auxiliary searches; no source-family witness is implied.
 rng=random.Random(983);aux=dict(cases=0,failures=[],status='finite arbitrary increasing log-concave weight experiment')
 for trial in range(1000):
  j=rng.randrange(2,18);rs=sorted([F(rng.randrange(10,80),10) for _ in range(j)],reverse=True);ww=[F(1)]
  for r in rs:ww.append(ww[-1]*r)
  assert all(ww[i]<=ww[i+1] for i in range(j)) and all(ww[i]**2>=ww[i-1]*ww[i+1] for i in range(1,j))
  for s in [0,2,9]:
   aux['cases']+=1;bad=check(ww,j,s)
   if bad:aux['failures'].append(dict(j=j,s=s,w=list(map(str,ww)),bad=[(n,str(g)) for n,g in bad]));break
  if aux['failures']:break
 (O/'increasing-lc-reproduced.json').write_text(json.dumps(aux,indent=2)+'\n');print(json.dumps(aux),flush=True)
if __name__=='__main__':run()
